-- El juego de caracteres se fija SIEMPRE: el cliente `mysql` lo toma del entorno y en un
-- contenedor sin locale eso es latin1, que convierte cada tilde en mojibake sin dar error.
SET NAMES utf8mb4;
-- Fotos de puntos de interés (poi-images.js)
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Calasparra-santuario-Virgen-de-la-Esperanza.jpg?width=1280', source = 'Decreto n.º 55/2015, de 17 de abril, Plan de Gestión Integral de los espacios protegidos Red Natura 2000 del Noroeste de la Región de Murcia (BORM n.º 109, de 14 de mayo de 2015, suplemento n.º 1, anuncio 6009), volumen II: §13.1.4.4 enumera el «Área recreativa del Santuario Virgen de la Esperanza» entre las infraestructuras de uso público de la ZEC y §13.1.8 sitúa el «Albergue del Santuario de la Esperanza» dentro del área de la Reserva Natural de Cañaverosa; §13.1.2.2 «Lugares de Interés Geológico» describe el segundo punto del LIG «Alrededores de Calasparra» como «la formación de conglomerados poligénicos pliocuaternarios donde está situado el Santuario Virgen de la Esperanza», «una zona muy rica desde el punto de vista estratigráfico». PDF consultado de primera mano el 2026-08-22 (194 MB; la capa de texto va con el desplazamiento de glifos descrito en anexos-normativos.json). IELIG (IGME), punto PTs095 «Terraza del Segura y mirador del santuario de Nª Sª de la Esperanza», consultado el 2026-08-22 en mapas.igme.es: interés principal geomorfológico, secundario tectónico e hidrogeológico, rasgo del Plioceno al Pleistoceno, unidad geotectónica Prebético. La descripción de la gruta y de las dos imágenes procede del catálogo de datos abiertos de la CARM «Monumentos en la Región de Murcia» (código 345), consultado el 2026-08-22 vía nexo.carm.es; ese catálogo NO tiene campo de declaración BIC y Wikidata (Q94393191) no le asigna código P808, así que aquí NO se afirma que el santuario sea Bien de Interés Cultural. Coordenada de OpenStreetMap (node/1682134193, amenity=place_of_worship, ODbL), que es la más precisa de las tres disponibles: el punto del IELIG cae a 37 m y el del catálogo de monumentos, a 550 m y fuera del límite oficial. Sin foto de licencia admisible localizada (§4.6); Wikimedia Commons (foto: No machine-readable author provided. Darabuc~commonswiki assumed (b…, Public domain)' WHERE slug = 'santuario-virgen-de-la-esperanza' AND park_id = (SELECT id FROM parks WHERE slug = 'sotos-y-bosques-de-ribera-de-canaverosa');
